"""
    :param chrompairs:
    :param select:
    :param which:
    :return:
    """
def filter_hdf_paths(chrompairs: Any, select: Any, which: Any) -> object {
    if (which == 'target') {
        load_paths = [
            t[2]
            for t in chrompairs
            if (t[1] == select)
        ];
    } elif (which == 'query') {
        load_paths = [
            t[2]
            for t in chrompairs
            if (t[0] == select)
        ];
    } else {
        raise ValueError(
            'Reference has to be specified as target or query, not as {}'.format(which)
        );
    }
    return load_paths;
}

"""Returns the value at the end of the list of keys.

    >>> d = {'a': 1, 'c': {'e': 5, 'd': 4}, 'b': 2, 'f': {'g': {'h': 8}}}
    >>> valueForKeyList(d, ('q',), "foo")
    'foo'
    >>> valueForKeyList(d, (), "foo")
    {'a': 1, 'c': {'e': 5, 'd': 4}, 'b': 2, 'f': {'g': {'h': 8}}}
    """
def valueForKeyList(d: Any, keys: Any, `default: Any = None) -> object {
    for key in keys {
        if not (key in d) {
            return `default;
        }
        d = d[key];
    }
    return d;
}

